package ama.meeting;
import ama.access.MeetingAccess;import ama.contract.IdentityContracts.*;import ama.db.TransactionRunner;import ama.task.SubjectFencePort;
import java.sql.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import javax.sql.DataSource;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
/** Real JDBC access gate and transaction runner with metadata doubles; not MySQL/race qualification. */
class Task12WorkspaceNavigationTest {
 static final String M="00000000-0000-4000-8000-000000000001",I="00000000-0000-4000-8000-000000000002",R="00000000-0000-4000-8000-000000000003",T="00000000-0000-4000-8000-000000000004",B="00000000-0000-4000-8000-000000000005",E="00000000-0000-4000-8000-000000000006";
 Actor actor=new Actor("owner",Status.ACTIVE,Set.of(Role.USER));DataSource source;TransactionRunner tx;JdbcMeetingAccess access;JdbcWorkspaceNavigationReader reader;List<String> sql;Map<String,Object> root;boolean candidate,raw,missing,disabled;long history=4L;String parentMeeting=M,candidateColumn="minutes_revision_id";
 static Map<String,Object> row(Object...v){var m=new LinkedHashMap<String,Object>();for(int n=0;n<v.length;n+=2)m.put((String)v[n],v[n+1]);return m;}
 @BeforeEach void setup()throws Exception{
  sql=new ArrayList<>();source=mock(DataSource.class);root=row("id",M,"owner_id","owner","revision",9007199254740993L,"access_revision",7L,"cancel_epoch",0L,"stage","MINUTES_PENDING","lifecycle","ACTIVE","governance_state","ACTIVE","ever_published",false,"info_revision_id",I,"roster_revision_id",R,"transcript_revision_id",T,"transcript_confirmation_id",null,"minutes_revision_id",B,"element_set_id",E);
  when(source.getConnection()).thenAnswer(call->{var c=mock(Connection.class);when(c.getAutoCommit()).thenReturn(true);when(c.createStatement()).thenReturn(mock(Statement.class));when(c.prepareStatement(anyString())).thenAnswer(q->{String text=q.getArgument(0);sql.add(text);assertTrue(text.startsWith("SELECT "),text);var st=mock(PreparedStatement.class);when(st.getConnection()).thenReturn(c);when(st.executeQuery()).thenAnswer(x->result(rows(text)));return st;});return c;});
  tx=new TransactionRunner(source);var fences=mock(SubjectFencePort.class);var subject=mock(SubjectFencePort.LockedSubject.class);when(subject.businessVersion()).thenAnswer(x->root.get("revision"));when(fences.lock(any(),eq(false))).thenReturn(Optional.of(subject));access=new JdbcMeetingAccess(source,tx,fences);reader=new JdbcWorkspaceNavigationReader(source,tx,access,WorkspaceReadBudget.DEFAULT);
 }
 List<Map<String,Object>> rows(String q){
  if(q.contains(" FROM enterprise_identity "))return List.of(q.startsWith("SELECT status")?row("status",disabled?"DISABLED":"ACTIVE"):row("enterprise_id",actor.enterpriseId(),"status",disabled?"DISABLED":"ACTIVE"));
  if(q.contains(" FROM meeting "))return List.of(root);
  if(q.contains(" FROM meeting_access_grant "))return List.of(row("roster_id",R));
  if(q.contains(" FROM roster_member "))return List.of(row("member_id",I));
  if(q.contains(" FROM generation_candidate "))return candidate&&q.contains(candidateColumn)?List.of(row("id",I)):List.of();
  if(missing)return List.of();
  if(q.contains(" FROM meeting_info_revision "))return List.of(row("id",I,"meeting_id",parentMeeting,"revision",1L));
  if(q.startsWith("SELECT id FROM roster_revision"))return List.of(row("id",R));
  if(q.contains(" FROM roster_revision "))return List.of(row("id",R,"meeting_id",parentMeeting,"revision",2L,"state","CONFIRMED"));
  if(q.contains(" FROM transcript_revision "))return List.of(row("id",T,"meeting_id",parentMeeting,"revision",3L,"kind",raw?"RAW":"WORKING"));
  if(q.contains(" FROM transcript_confirmation ")){assertFalse(q.contains("meeting_revision"),"V011 confirmation has no revision counter");return List.of(row("id",I,"meeting_id",parentMeeting,"revision_id",T));}
  if(q.contains(" FROM minutes_revision "))return List.of(row("id",B,"meeting_id",parentMeeting,"revision",history));
  if(q.contains(" FROM element_set "))return List.of(row("id",E,"meeting_id",parentMeeting,"revision",history+1));
  throw new AssertionError(q);
 }
 ResultSet result(List<Map<String,Object>> rows)throws Exception{
  var rs=mock(ResultSet.class);var i=new AtomicInteger(-1);var columns=rows.isEmpty()?List.<String>of():new ArrayList<>(rows.getFirst().keySet());var meta=mock(ResultSetMetaData.class);when(meta.getColumnCount()).thenReturn(columns.size());when(rs.getMetaData()).thenReturn(meta);when(rs.next()).thenAnswer(x->i.incrementAndGet()<rows.size());when(rs.getString(anyInt())).thenAnswer(x->(String)rows.get(i.get()).get(columns.get((int)x.getArgument(0)-1)));when(rs.getString(anyString())).thenAnswer(x->(String)rows.get(i.get()).get(x.getArgument(0)));when(rs.getLong(anyString())).thenAnswer(x->((Number)rows.get(i.get()).get(x.getArgument(0))).longValue());when(rs.getBoolean(anyString())).thenAnswer(x->Boolean.TRUE.equals(rows.get(i.get()).get(x.getArgument(0))));return rs;
 }
 @Test void currentReferencesAreExactAndNeverSelectContentOrPrivateHistory(){var value=reader.read(actor,M);assertEquals("9007199254740993",value.revisionToken());assertEquals("OWNER",value.relation());assertEquals(T,value.saved().transcriptRevisionId());assertEquals(B,value.saved().minutesRevisionId());assertEquals(E,value.saved().elementSetId());assertEquals("RECHECK_REQUIRED",value.contentEligibility());assertTrue(sql.stream().noneMatch(q->q.contains("SELECT *")||q.contains("display_name")||q.contains("summary")||q.contains("body")||q.contains("request_manifest")||q.contains("durable_task")));assertEquals(1,sql.stream().filter(q->q.startsWith("SELECT enterprise_id,status")).count());}
 @Test void memberUsesGenuineConfirmedGrantAndOnlyEffectiveSavedIds(){actor=new Actor("member",Status.ACTIVE,Set.of(Role.USER));var value=reader.read(actor,M);assertEquals("MEMBER",value.relation());assertEquals("MEMBER_READ_ONLY",value.navigationState());assertTrue(sql.stream().anyMatch(q->q.contains("meeting_access_grant")));assertTrue(sql.stream().noneMatch(q->q.contains("template_revision")||q.contains("generation_input")||q.contains("publication_submission")));}
 @Test void rawAndCandidatePointersNeverBecomeEffectiveSavedReferences(){raw=true;assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));raw=false;candidate=true;for(String column:List.of("minutes_revision_id","element_set_id")){candidateColumn=column;assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));}}
 @Test void danglingAndCrossMeetingParentsFailClosed(){missing=true;assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));missing=false;parentMeeting=I;assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));}
 @Test void disabledAndOutsiderDoNotReadNavigationParents(){disabled=true;assertThrows(MeetingAccess.AccessDeniedException.class,()->reader.read(actor,M));assertTrue(sql.stream().noneMatch(q->q.contains("meeting_info_revision")));disabled=false;root.put("roster_revision_id",null);actor=new Actor("outsider",Status.ACTIVE,Set.of(Role.PLATFORM_ADMIN));assertThrows(MeetingAccess.AccessDeniedException.class,()->reader.read(actor,M));}
 @Test void noAmbientTransactionOrForeignDataSource(){assertThrows(IllegalArgumentException.class,()->new JdbcWorkspaceNavigationReader(mock(DataSource.class),tx,access,WorkspaceReadBudget.DEFAULT));assertThrows(WorkspaceReadBudget.Unavailable.class,()->tx.required(()->reader.read(actor,M)));assertTrue(sql.isEmpty());}
 @Test void confirmationUsesActualV011ColumnsAndMustPointToCurrentWorking(){root.put("transcript_confirmation_id",I);assertEquals(I,reader.read(actor,M).saved().transcriptConfirmationId());root.put("transcript_revision_id",null);assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));}
 @Test void cumulativeBudgetStopsBeforeNextParentSelect(){reader=new JdbcWorkspaceNavigationReader(source,tx,access,new WorkspaceReadBudget.Limits(27000,100000,100000,100000,4096,16384,java.time.Duration.ofSeconds(5)));assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));assertTrue(sql.stream().anyMatch(q->q.contains(" FROM meeting ")));assertTrue(sql.stream().noneMatch(q->q.contains(" FROM meeting_info_revision ")));}
 @Test void absentEffectiveReferencesStayNullAndPublishedOwnerIsReadOnly(){for(String key:List.of("roster_revision_id","transcript_revision_id","transcript_confirmation_id","minutes_revision_id","element_set_id"))root.put(key,null);root.put("ever_published",true);var value=reader.read(actor,M);assertEquals("PUBLISHED_READ_ONLY",value.navigationState());assertNull(value.saved().transcriptRevisionId());assertNull(value.saved().minutesRevisionId());assertNull(value.saved().elementSetId());assertEquals(I,value.saved().infoRevisionId());}
 @Test void independentSavedHistoryCountersMayExceedMeetingRevision(){history=9007199254740994L;var value=reader.read(actor,M);assertEquals(B,value.saved().minutesRevisionId());assertEquals(E,value.saved().elementSetId());}
 @Test void budgetAndCancellationStopBeforeAnySql(){reader=new JdbcWorkspaceNavigationReader(source,tx,access,new WorkspaceReadBudget.Limits(64,64,64,64,1,1,java.time.Duration.ofSeconds(5)));assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));assertTrue(sql.isEmpty());Thread.currentThread().interrupt();try{assertThrows(WorkspaceReadBudget.Unavailable.class,()->reader.read(actor,M));}finally{Thread.interrupted();}}
}
